const input = $input.first().json;

const originalJobs = $('Webhook').first().json.body.jobs || [];
const jobById = {};
for (const j of originalJobs) { jobById[j.job_id] = j; }

let text = "";
if (input.content && input.content.parts && input.content.parts[0] && input.content.parts[0].text) {
  text = input.content.parts[0].text;
} else if (input.text) {
  text = input.text;
} else if (input.output) {
  text = input.output;
} else if (input.response) {
  text = input.response;
} else if (input.message) {
  text = input.message;
} else {
  throw new Error("Could not find Gemini text output. Full input: " + JSON.stringify(input));
}

text = text.replace(/```json/g, "").replace(/```/g, "").trim();

let jobs;
try {
  jobs = JSON.parse(text);
} catch (error) {
  throw new Error("Could not parse Gemini response as JSON. Raw Gemini response: " + text);
}

if (!Array.isArray(jobs)) {
  if (jobs && typeof jobs === "object") {
    jobs = [jobs];
  } else {
    throw new Error("Gemini response was not an array or object. Raw Gemini response: " + text);
  }
}

// --- Deterministic experience-gap penalty ---
// Gemini is instructed to apply this penalty itself, but batch/JSON-mode
// calls have been confirmed (empirically, against real jobs) to silently
// skip it while still applying the skill-fit scoring correctly. Recompute
// it in code so it's guaranteed to fire every time, instead of depending on
// prompt compliance.

const MAX_PLAUSIBLE_YEARS = 20; // guards against false positives like "85 years
// of experience" (company-history boilerplate) being misread as a job requirement.

const EXPLICIT_PATTERNS = [
  /(\d{1,2})\s*\+\s*years?/gi,
  /(\d{1,2})\s*-\s*\d{1,2}\s*years?/gi,
  /minimum\s+(?:of\s+)?(\d{1,2})\s*years?/gi,
  /at\s+least\s+(\d{1,2})\s*years?/gi,
  /(\d{1,2})\s*years?\s+of\s+(?:professional\s+|relevant\s+|related\s+)?experience/gi,
];

const TITLE_TIERS = [
  [/\b(staff|principal|director|head of|vp|vice president)\b/i, 8],
  [/\b(senior|sr\.?|lead)\b/i, 6],
  [/\b(associate|analyst i\b|junior|jr\.?|entry.?level)\b/i, 0],
];

function inferRequiredYears(title, description) {
  const text = description || "";
  for (const pattern of EXPLICIT_PATTERNS) {
    pattern.lastIndex = 0;
    let m;
    while ((m = pattern.exec(text)) !== null) {
      const years = parseInt(m[1], 10);
      if (years > 0 && years <= MAX_PLAUSIBLE_YEARS) return years;
    }
  }
  for (const [pattern, years] of TITLE_TIERS) {
    if (pattern.test(title || "")) return years;
  }
  return 3; // mid-level default, matches "no seniority modifier -> 2-5 years"
}

function penaltyForYears(years) {
  if (years <= 5) return 0;
  if (years <= 7) return 15;
  if (years <= 9) return 30;
  return 45;
}

return jobs.map(job => {
  const originalJob = jobById[job.job_id] || {};
  const requiredYears = inferRequiredYears(job.title, originalJob.description);
  const penalty = penaltyForYears(requiredYears);
  const rawScore = Number(job.match_score) || 0;
  const adjustedScore = Math.max(0, rawScore - penalty);

  return {
    json: {
      job_id: job.job_id || "",
      date_posted: originalJob.date_posted || "",
      title: job.title || "",
      company: job.company || "",
      location: job.location || "",
      url: job.url || "",
      match_score: adjustedScore,
      tech_stack: Array.isArray(job.tech_stack) ? job.tech_stack.join(", ") : job.tech_stack || "",
      missing_skills: Array.isArray(job.missing_skills) ? job.missing_skills.join(", ") : job.missing_skills || "",
      pitch: job.pitch || ""
    }
  };
});

